package de.fahrerabrechnung.domain.violation.weekly

import de.fahrerabrechnung.domain.violation.driving.RuleLaw
import de.fahrerabrechnung.domain.violation.input.*
import de.fahrerabrechnung.domain.violation.rest.*
import java.time.Instant
import org.junit.Assert.*
import org.junit.Test

/** Fixed debt inputs and hand calculations from M0; not debts generated by the tested solver. */
class CompensationReferenceTest {
    private fun at(value: String) = Instant.parse(value)
    private val date = at("2026-09-19T00:00:00Z")
    private fun debt(id: String = "d1", minutes: Long = 1260,
        week: String = "2026-09-07T00:00:00Z", due: String = "2026-10-05T00:00:00Z") =
        WeeklyCompensationDebt(id, "origin-$id", "candidate-$id",
            InputRange(at(week), at(week).plusSeconds(86400)), at(week), minutes * 60,
            at(due), RuleLaw("W04", "Art.8(6b)", "2020-08-20", listOf("Q01-K-DE")),
            listOf(WeeklyRestriction.L02_UTC_WEEK_PROJECTION_ONLY))
    private fun rest(start: Instant = date, minutes: Int = 1920): RestCandidate =
        DailyRestCalculator.calculate(RestFixture(start, prefix = false).r(minutes).snapshot()).candidates.single()
    private fun paying(r: RestCandidate, debts: List<WeeklyCompensationDebt>) =
        CompensationAllocator.choices(r, debts) {}.filter { it.reservations.isNotEmpty() }.toList()

    @Test fun LG64Required24HoursHas21HoursCompensationDueAtEndOfThirdFollowingWeek() {
        val r = rest(at("2026-09-12T00:00:00Z"), 1440)
        assertEquals(1260 * 60L, WeeklyTime.REGULAR - r.netRestSeconds)
        assertEquals(at("2026-10-05T00:00:00Z"), WeeklyTime.due(at("2026-09-07T00:00:00Z")))
    }
    @Test fun LG64ThirtyHoursHas15HoursCompensation() { assertEquals(900 * 60L, WeeklyTime.REGULAR - rest(minutes = 1800).netRestSeconds) }
    @Test fun LG64FortyFourHours59HasOneMinuteCompensation() { assertEquals(60L, WeeklyTime.REGULAR - rest(minutes = 2699).netRestSeconds) }
    @Test fun LG65CompletionExactlyAtDueIsOnTime() {
        val r = rest(at("2026-10-03T16:00:00Z"))
        val suffix = paying(r, listOf(debt())).single { it.reservations.single().range.end == r.range.end }
        assertTrue(suffix.reservations.single().onTime)
        assertEquals(0, suffix.reservations.single().completedLateBySeconds)
    }
    @Test fun LG65OneMinuteLateIsStillLateAfterCompletePayment() {
        val r = rest(at("2026-10-03T16:01:00Z"))
        val suffix = paying(r, listOf(debt())).single { it.reservations.single().range.end == r.range.end }
        assertFalse(suffix.reservations.single().onTime)
        assertEquals(60, suffix.reservations.single().completedLateBySeconds)
        // Another legal attribution (prefix compensation) must be retained, never hidden by FIFO.
        assertTrue(paying(r, listOf(debt())).any { it.reservations.single().onTime })
    }
    @Test fun LG66NinePlus21IsAContinuousAllocation() {
        val r = rest(minutes = 1800)
        paying(r, listOf(debt())).forEach {
            CompensationAllocator.validate(r, it, listOf(debt()))
            assertEquals(540 * 60L, it.base.sumOf { slice -> slice.seconds })
            assertEquals(1260 * 60L, it.reservations.single().seconds)
        }
        assertEquals(2, paying(r, listOf(debt())).size)
    }
    @Test fun LG66SeparateTenAndElevenHourRestsCannotBeCombinedInto21HoursCompensation() {
        assertTrue(paying(rest(minutes = 600), listOf(debt())).isEmpty())
        assertTrue(paying(rest(minutes = 660), listOf(debt())).isEmpty())
    }
    @Test fun LG67ThirtyTwoHoursCannotPayTwo21HourDebts() {
        val ds = listOf(debt(), debt("d2", week = "2026-08-31T00:00:00Z", due = "2026-09-28T00:00:00Z"))
        val r = rest()
        val choices = paying(r, ds)
        assertEquals(setOf("d1", "d2"), choices.flatMap { it.reservations }.map { it.debtId }.toSet())
        assertTrue(choices.all { it.reservations.size == 1 })
        choices.forEach { CompensationAllocator.validate(r, it, ds) }
    }
    @Test fun LG68CompensationLeavesNineNotElevenHoursOfDailyBase() {
        val ds = listOf(debt())
        val r = rest(minutes = 1800)
        assertTrue(paying(r, ds).all { it.base.sumOf { slice -> slice.seconds } == 32400L })
    }
    private fun attributed(prior: Int): DailyRestCalculation {
        val snapshot = RestFixture(date, priorReductions = prior).w(900).r(1800).snapshot()
        val physical = DailyRestCalculator.calculate(snapshot)
        val target = physical.candidates.single { it.range.start == date.plusSeconds(900 * 60) }
        val choice = paying(target, listOf(debt())).single { it.base.first().range.start == target.range.start }
        val allocation = DailyRestAllocation(choice.base, emptyList(), listOf(RestRestriction.L04_COMPENSATION_ASSIGNMENT_UNCONFIRMED))
        return DailyRestCalculator.calculate(snapshot, attribution = DailyRestAttribution(
            physical.candidates.map { it.id }.toSet(), mapOf(target.id to allocation)))
    }
    @Test fun LG68AvailableDailyReductionIsConsumedWithoutWeeklyReset() {
        val result = attributed(0)
        val window = result.windows.single { it.referenceStart == date }
        assertEquals(DailyRestKind.REDUCED, window.options.single().kind)
        assertEquals(1, result.finalCounters.single().minimumObservedCount)
        assertNull(result.finalCounters.single().provenRemaining)
    }
    @Test fun LG68ThreeEarlierDailyReductionsDoNotTurnThirtyHoursIntoAnElevenHourBase() {
        val result = attributed(3)
        assertTrue(result.findings.any { it.assessedRange.start == date && it.missingRestSeconds == 7200L })
        assertTrue(result.findings.none { it.normalRuleDeficitIsProved })
        // Three independently proved earlier reductions remain exhausted; no fourth is created.
        assertTrue(result.finalCounters.all { it.provenRemaining == 0 })
    }
    @Test fun LG104OneCrossWeekRestHasTwoDifferentDueVariants() {
        val range = InputRange(at("2026-09-13T23:00:00Z"), at("2026-09-14T23:00:00Z"))
        assertEquals(listOf(at("2026-09-07T00:00:00Z"), at("2026-09-14T00:00:00Z")), WeeklyTime.weeks(range))
        assertEquals(listOf(at("2026-10-05T00:00:00Z"), at("2026-10-12T00:00:00Z")), WeeklyTime.weeks(range).map(WeeklyTime::due))
    }
    @Test fun LG105ThirtyTwoHoursRetainsBothDebtChoicesButNeverPaysBoth() {
        val ds = listOf(debt("early", 840, "2026-08-31T00:00:00Z", "2026-09-28T00:00:00Z"), debt("later"))
        val r = rest()
        val choices = paying(r, ds).filter { it.base.sumOf { s -> s.seconds } >= 39600 }
        assertEquals(setOf("early", "later"), choices.flatMap { it.reservations }.map { it.debtId }.toSet())
        assertTrue(choices.all { it.reservations.size == 1 })
    }
    @Test fun LG105FortySixHoursCanReserveBothWholeDebtsAndElevenHourBase() {
        val ds = listOf(debt("early", 840, "2026-08-31T00:00:00Z", "2026-09-28T00:00:00Z"), debt("later"))
        val r = rest(minutes = 2760)
        val choices = paying(r, ds).filter { it.reservations.size == 2 }
        assertFalse(choices.isEmpty())
        choices.forEach { choice ->
            assertEquals(39600, choice.base.sumOf { it.seconds })
            assertEquals(2100 * 60L, choice.reservations.sumOf { it.seconds })
            CompensationAllocator.validate(r, choice, ds)
        }
    }
    @Test fun ExtraRestHasNoDebtInputToInventOrPay() { assertEquals(1, CompensationAllocator.choices(rest(), emptyList()) {}.count()) }
    @Test fun OpenRestCannotReceiveAnAssuredCompensationReservation() {
        assertEquals(1, CompensationAllocator.choices(rest().copy(actualEndProved = false), listOf(debt())) {}.count())
    }
    @Test fun DebtsFromTheFutureCannotBePaidInAnEarlierRest() {
        val d = debt().copy(originRange = InputRange(date.plusSeconds(86400), date.plusSeconds(172800)))
        assertTrue(paying(rest(), listOf(d)).isEmpty())
    }
    @Test fun CompensationSearchHonoursCancellation() {
        var count = 0
        try {
            CompensationAllocator.choices(rest(), listOf(debt())) { count++; throw IllegalStateException("synthetic-cancel") }.toList()
            fail("cancellation swallowed")
        } catch (expected: IllegalStateException) { assertEquals("synthetic-cancel", expected.message) }
        assertEquals(1, count)
    }
}
